import { isReportSignatureImageDataUrl, REPORT_SIGNATURE_ON_FILE } from './reportSignatureField.ts'

/** Label after migration (Superintendent Report first field). */
export const REPORT_FIELD_LABEL_JOB_COMPLETION = 'How complete is the job?'
/** JSON key in older `reports.field_values` before rename. */
export const REPORT_FIELD_LABEL_LEGACY_WHO = 'Who was on the job?'

export function normalizePercentFieldValueToString(raw: string | undefined | null): string {
  if (raw == null || raw === '') return '0'
  const n = Number.parseInt(String(raw).trim(), 10)
  if (Number.isNaN(n)) return '0'
  return String(Math.max(0, Math.min(100, n)))
}

export function tryParsePercent0to100(raw: string | undefined | null): number | null {
  if (raw == null || raw === '') return null
  const n = Number.parseInt(String(raw).trim(), 10)
  if (Number.isNaN(n) || n < 0 || n > 100) return null
  return n
}

/** One-line value for read-only report body. */
export function formatReportFieldValueForRead(
  label: string,
  value: string,
  opts?: { inputType?: 'long_text' | 'percent_0_100' | 'signature_png' | null },
): string {
  const t = opts?.inputType
  if (t === 'signature_png' || isReportSignatureImageDataUrl(value)) {
    return ''
  }
  if (t === 'percent_0_100' || label === REPORT_FIELD_LABEL_JOB_COMPLETION) {
    const p = tryParsePercent0to100(value)
    if (p != null) return `${p}%`
  }
  if (label === REPORT_FIELD_LABEL_LEGACY_WHO) {
    const p = tryParsePercent0to100(value)
    if (p != null) return `${p}%`
  }
  return value
}

/** Heading shown above a field in read-only view (migrates legacy key to the new copy). */
export function displayLabelForFieldKey(fieldKey: string): string {
  if (fieldKey === REPORT_FIELD_LABEL_LEGACY_WHO) return REPORT_FIELD_LABEL_JOB_COMPLETION
  return fieldKey
}

export function isPercentFieldKey(label: string): boolean {
  return label === REPORT_FIELD_LABEL_JOB_COMPLETION || label === REPORT_FIELD_LABEL_LEGACY_WHO
}

/** One line for Stages Notes thread preview under the report template name. */
export function formatReportFieldValueForThreadSummary(label: string, value: string): string {
  const t = (value ?? '').trim()
  if (isReportSignatureImageDataUrl(t)) {
    return REPORT_SIGNATURE_ON_FILE
  }
  if (isPercentFieldKey(label)) {
    const p = tryParsePercent0to100(t)
    if (p != null) return `I think the job is ${p}% complete`
  }
  return t
}

type FieldForSubmit = { label: string; input_type?: string | null }

/** What the form opened its percent on, for `fieldValueForSubmit` (punch list #189, PR 5a). */
export type PercentSubmitOpts = {
  /** The job's own percent the untouched field opened on; null when the job has none or the form seeds nothing. */
  percentSeed?: number | null
  /** Report by line (v2.5663): the lines' number takes the field, so the seed never applies. */
  linesActive?: boolean
}

/**
 * The percent a report files from its percent field (punch list #189, PR 5a). An untouched field files the number
 * the form opened on (`seed`, the job's own percent), a pick files the pick, and with no number on record an
 * untouched field files 0. The effect that writes the seed into the form's values is passive, so a Save in the
 * moment before it ran read the field as untouched and filed 0 while the field said 40 (the CI flake of 2026-10-30):
 * this rule gives Save, the Save button's words and the job's mirrored percent the same number whichever moment the
 * press lands in. With the lines active the lines' own number takes the field, so the seed never applies.
 */
export function percentFieldValueForSubmit(raw: string | undefined | null, seed: number | null | undefined, linesActive = false): string {
  if (!linesActive && raw == null && seed != null) return normalizePercentFieldValueToString(String(seed))
  return normalizePercentFieldValueToString(raw)
}

export function fieldValueForSubmit(
  f: FieldForSubmit,
  fieldValues: Record<string, string>,
  opts?: PercentSubmitOpts,
): string {
  const it = f.input_type ?? 'long_text'
  if (it === 'percent_0_100') {
    return percentFieldValueForSubmit(fieldValues[f.label], opts?.percentSeed ?? null, opts?.linesActive ?? false)
  }
  if (it === 'signature_png') {
    return fieldValues[f.label] ?? ''
  }
  return fieldValues[f.label] ?? ''
}
